INSERT INTO "public"."dev_prayers" ("id", "lesson_id", "role", "text_content", "display_order") VALUES
('94b023b1-c133-498c-8ed4-29158397071b', 'a8bf574c-d9da-4e23-b7fe-6281e98d9b79', 'Individual', 'Senhor Deus, reconheço que tudo o que possuo provém da Tua soberana graça. Perdoa a minha negligência e as desculpas que tantas vezes uso para justificar a inércia. Concede-me autogoverno, coragem e integridade para administrar com sabedoria e zelo cada dom, tempo e oportunidade que colocaste em minhas mãos. Que a minha conduta diária seja pautada pelo trabalho diligente e pela fidelidade prática, honrando o Teu santo nome até o dia da nossa prestação de contas. Em nome de Jesus, amém.', 1),
('e01ad784-6e89-49db-a74b-5d0414b67a29', 'a1ffab8e-4ca4-459c-8993-561c6001587d', 'Pai', 'Senhor, ajuda-me a ensinar meus filhos a cuidarem com zelo de tudo o que Tu nos confias.', 1),
('fce5df71-19a5-4c08-955b-9151e78ecba3', 'a1ffab8e-4ca4-459c-8993-561c6001587d', 'Filho', 'Jesus, obrigado pelos meus dons. Quero usar minhas mãos e meu coração para Te agradar.', 2),
('edb873d6-434f-44c7-a665-57494b0f9442', 'a1ffab8e-4ca4-459c-8993-561c6001587d', 'Juntos', 'Pai Celeste, queremos ser servos fiéis, cuidando com amor de tudo o que nos deste. Amém.', 3),
('d7904ee2-62b6-48bd-a877-38c01315b443', '38f5f8c1-9de4-4a44-9eb3-9f516a8edd90', 'Pai', 'Senhor, ajuda-me a ser um exemplo de diligência e integridade no cumprimento dos meus deveres diários.', 1),
('14427513-0edd-43b4-b129-21e1f62d0e64', '38f5f8c1-9de4-4a44-9eb3-9f516a8edd90', 'Filho', 'Deus, perdoa minha preguiça e dá-me coragem para usar meus talentos e estudos para a Tua glória.', 2),
('9022e2bf-80cd-43c2-89c2-78af66ebe1fd', '38f5f8c1-9de4-4a44-9eb3-9f516a8edd90', 'Juntos', 'Pai celestial, ensina nossa família a administrar com sabedoria tudo o que nos deste. Amém.', 3),
('0d90fc7d-02e3-47d0-85f9-270480aa9607', '69c94ef8-3555-4f68-bcff-5b8350f5a662', 'Pai', 'Senhor, capacita-me a ser um exemplo consistente de trabalho, disciplina e integridade moral para o meu filho.', 1),
('6d926f7b-1822-4955-a118-5f506e458dde', '69c94ef8-3555-4f68-bcff-5b8350f5a662', 'Filho', 'Deus, afasta de mim a preguiça e as desculpas, dando-me firmeza para administrar bem meu tempo e meus deveres.', 2),
('d77247f0-952b-47f3-aa11-62d7c62b0840', '69c94ef8-3555-4f68-bcff-5b8350f5a662', 'Juntos', 'Pai celestial, faz de nossa casa um lugar de honra, fidelidade e prestação de contas sincera diante de Ti. Amém.', 3),
('8395da74-cdad-4264-862e-211b5775f746', '1278750b-d391-49fb-ad90-704ad9414304', 'Individual', 'Senhor Deus, Tu me confiaste dons, tempo e pessoas para cuidar com retidão. Perdoa-me pelos momentos em que negligenciei meus deveres ou agi com egoísmo, esquecendo que presto contas a Ti. Concede-me um coração vigilante, sóbrio e comprometido com a Tua vontade. Que a minha conduta diária reflita fidelidade inabalável, tanto nas pequenas tarefas quanto nas grandes decisões. Em nome de Jesus, amém.', 1),
('c385600d-4397-4e49-b8c1-30f79ee53b2b', 'a34d02ce-8726-4843-8247-3e6f31b75ab7', 'Pai', 'Senhor, ensina nosso lar a ter um coração fiel e zeloso em cada pequeno dever diário.', 1),
('222eb4ba-0569-428a-b213-e0440f51b692', 'a34d02ce-8726-4843-8247-3e6f31b75ab7', 'Filho', 'Jesus, ajuda minhas mãozinhas a cuidarem com carinho dos meus brinquedos e da minha família.', 2),
('9ac89617-c095-431d-a7b6-d465c437c85d', 'a34d02ce-8726-4843-8247-3e6f31b75ab7', 'Juntos', 'Pai do Céu, queremos ser ajudantes bons, atentos e obedientes todos os dias. Amém!', 3),
('cf2a6e81-6eb1-4089-b57c-171d3a0a6070', '3b668d23-afb2-4535-b553-2666e511d9ff', 'Pai', 'Senhor, ajuda-me a liderar minha casa com sabedoria, sendo um exemplo visível de dedicação, integridade e fidelidade aos Teus princípios.', 1),
('500cc264-f66a-4878-9c67-52763a20f194', '3b668d23-afb2-4535-b553-2666e511d9ff', 'Filho', 'Pai celestial, dá-me forças para vencer a preguiça nos estudos e para agir com retidão mesmo quando ninguém estiver me observando.', 2),
('66e9d634-c49f-4ad2-ae81-047009e1672c', '3b668d23-afb2-4535-b553-2666e511d9ff', 'Juntos', 'Senhor Deus, consagramos nosso tempo e nossas tarefas a Ti, buscando sempre cumprir com zelo tudo o que nos confiaste. Amém.', 3),
('4f8db420-25fb-40b6-92ac-c556bd0c9c31', '6da16cbc-f460-415d-bbec-3b6b4affadd4', 'Pai', 'Senhor, ajuda-me a ser um modelo de vigilância e integridade, guiando meus filhos pelo exemplo e pelo temor a Ti.', 1),
('d5b6aca0-39f2-4fa2-9d52-516b7775aa34', '6da16cbc-f460-415d-bbec-3b6b4affadd4', 'Filho', 'Pai celestial, concede-me maturidade e disciplina para honrar a confiança recebida, vivendo com retidão mesmo quando ninguém vê.', 2),
('799b63bb-0164-4cb0-bc52-6fdfa5818462', '6da16cbc-f460-415d-bbec-3b6b4affadd4', 'Juntos', 'Senhor, firma nossa casa na Tua verdade e torna-nos servos fiéis até o dia do Teu retorno. Amém.', 3),
('31352869-5920-4c49-828e-34d7a3109260', '9b0242c0-605b-46cd-a49f-d552ff629998', 'Individual', 'Senhor Deus, agradeço pelo dom do trabalho e pela oportunidade de produzir com as minhas próprias mãos. Livra-me da preguiça, do desânimo e da inclinação para a ociosidade. Concede-me integridade e disciplina para cumprir minhas obrigações com excelência e sem murmurar. Que a minha dedicação diária sirva de bom testemunho e me permita abençoar os que realmente precisam. Em nome de Jesus, amém.', 1),
('fc31d3be-314f-486e-b70b-789f04e1286d', '002f3307-7176-4f12-a7f0-62c3bb64633b', 'Pai', 'Senhor, dá-me sabedoria para ensinar meus filhos pelo exemplo de dedicação, paciência e amor no trabalho diário.', 1),
('ae6e5f4b-e3a4-4176-abdf-03de8099deda', '002f3307-7176-4f12-a7f0-62c3bb64633b', 'Filho', 'Jesus, ajuda minhas mãozinhas a cuidarem dos meus brinquedos e a nunca terem preguiça de ajudar.', 2),
('9bebdd02-9d10-4203-9ddf-7a2fb14e0aa1', '002f3307-7176-4f12-a7f0-62c3bb64633b', 'Juntos', 'Papai do Céu, abençoa a nossa família para que trabalhemos juntos em harmonia e nunca nos cansemos de fazer o bem. Amém.', 3),
('f1499402-1e00-4ec5-afb1-cd02c489b596', '36e289e5-6e47-4ad8-bd4b-e6d78fa1da5c', 'Pai', 'Senhor, ajuda-me a ser exemplo de trabalho diligente e a ensinar responsabilidade com sabedoria e amor.', 1),
('25b51cb0-1338-4794-b784-f255dfcc665f', '36e289e5-6e47-4ad8-bd4b-e6d78fa1da5c', 'Filho', 'Deus, dá-me ânimo para cumprir meus deveres sem reclamar e sem depender do esforço dos outros.', 2),
('081c82d7-7708-4429-bb80-b0e228396c28', '36e289e5-6e47-4ad8-bd4b-e6d78fa1da5c', 'Juntos', 'Pai celestial, ensina nossa família a cooperar unida e a nunca se cansar de fazer o bem. Amém.', 3),
('d51539a0-5c88-42b1-9d7a-b6e35a6bc938', 'c459abdf-6f14-4b5f-bf29-523cd81403e9', 'Pai', 'Senhor, ajuda-me a ser exemplo vivo de diligência, honestidade e trabalho digno para minha casa.', 1),
('e59e6f95-c5c1-488b-af33-a90fe6746063', 'c459abdf-6f14-4b5f-bf29-523cd81403e9', 'Filho', 'Deus, afasta de mim a preguiça e ensina-me a cumprir meus deveres com integridade e autonomia.', 2),
('b81e8790-94d3-4046-bf45-b41df9dda0a0', 'c459abdf-6f14-4b5f-bf29-523cd81403e9', 'Juntos', 'Pai Celestial, consagra as obras de nossas mãos e dá-nos perseverança para nunca cansar de fazer o bem. Amém.', 3),
('63e2d04d-e747-4ad7-9c7b-b5bc63a6a61e', 'f0cbf542-a5a3-4519-a1ed-76f10984b76a', 'Individual', 'Senhor Deus, reconheço a responsabilidade que me confiaste de viver como um padrão autêntico de fidelidade. Guarda meus passos, meus lábios e minhas intenções. Dá-me graça e discernimento para cuidar da minha conduta, perseverando na Tua Palavra com integridade e amor sincero. Amém.', 1),
('57f10fe7-0049-42f2-b420-0572012d76ab', 'b6de0ee0-9505-41a6-b8c3-039c38224805', 'Pai', 'Senhor Deus, ajuda-me a ser um modelo diário de retidão, paciência e amor para guiar meu filho.', 1),
('ec610992-ef09-4d39-88b7-062f47938b7a', 'b6de0ee0-9505-41a6-b8c3-039c38224805', 'Filho', 'Jesus, ajuda meu coração a ser puro e faz as minhas palavras serem sempre doces e carinhosas.', 2),
('9152bb25-8f26-427e-81f2-7662bde999cd', 'b6de0ee0-9505-41a6-b8c3-039c38224805', 'Juntos', 'Pai celestial, que a nossa casa brilhe com a Tua verdade e que nossas atitudes glorifiquem o Teu nome. Amém!', 3),
('c61697c7-cd48-41a0-9010-737ba723710c', '6f4e8572-4dc3-4cf1-9f72-0214970f6341', 'Pai', 'Senhor, capacita-me a liderar meu filho com retidão, sendo o primeiro exemplo de fé, amor e integridade dentro do nosso lar.', 1),
('344767ef-2ea8-418c-8539-877df5e01359', '6f4e8572-4dc3-4cf1-9f72-0214970f6341', 'Filho', 'Deus, dá-me coragem para não ceder à pressão dos outros e guarda meu coração para que minhas palavras e atitudes te agradem.', 2),
('738c93e3-6a6e-4d76-b586-fb4aba749aa1', '6f4e8572-4dc3-4cf1-9f72-0214970f6341', 'Juntos', 'Pai celestial, ensina nossa família a cuidar da conduta diária, honrando o teu nome com vidas puras, obedientes e fiéis. Amém.', 3),
('46112143-cb61-419b-9fcd-8eeb4473a3f4', '74449d35-3442-4dae-a540-80b7cb84bd0a', 'Pai', 'Senhor Deus, peço que fortaleças meu filho para viver com firmeza, honra e discernimento, sendo guardado em pureza e retidão diante de Ti.', 1),
('7c90ec7f-8912-49ce-9360-d4dc788288cc', '74449d35-3442-4dae-a540-80b7cb84bd0a', 'Filho', 'Pai celestial, dá-me coragem e disciplina para guardar meu coração, controlar minhas escolhas e ser um exemplo vivo de fé e integridade.', 2),
('9598a9e8-2f53-46b5-b398-3a95c09cbc33', '74449d35-3442-4dae-a540-80b7cb84bd0a', 'Juntos', 'Senhor, consagramos nossas vidas e nosso lar ao Teu serviço. Que a nossa conduta diária glorifique o Teu santo nome. Amém.', 3);
